      "severity": "medium",
      "location": "src/tests/UnifiedAgent.test.ts",
      "description": "Missing test coverage: No test verifies that createSession() sends the correct title format, and Config.getInstance().getAgentId() is not explicitly mocked for HttpTransport tests"
    },
    {
      "severity": "low",
